import React, { useState } from 'react';
import ExpenseList from './ExpenseList';

function Dashboard({ trip, expenses, setExpenses }) {
    const [description, setDescription] = useState('');
    const [amount, setAmount] = useState('');
    const [paidBy, setPaidBy] = useState(trip.familyMembers[0]);

    const handleAddExpense = (e) => {
        e.preventDefault();
        const newExpense = {
            description,
            amount: parseFloat(amount),
            paidBy
        };
        setExpenses([...expenses, newExpense]);

        // Clear form
        setDescription('');
        setAmount('');
        setPaidBy(trip.familyMembers[0]);
    };

    return (
        <div>
            <h2>Trip: {trip.tripName}</h2>
            <h3>Add Expense</h3>
            <form onSubmit={handleAddExpense}>
                <label>Description:</label><br />
                <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} required /><br /><br />

                <label>Amount:</label><br />
                <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} required /><br /><br />

                <label>Paid By:</label><br />
                <select value={paidBy} onChange={(e) => setPaidBy(e.target.value)}>
                    {trip.familyMembers.map((member, index) => (
                        <option key={index} value={member}>{member}</option>
                    ))}
                </select><br /><br />

                <button type="submit">Add Expense</button>
            </form>

            <ExpenseList expenses={expenses} />
        </div>
    );
}

export default Dashboard;
